#define all(a) (a).begin(),(a).end()
#define sz(a) (int)(a).size()
#define eps (1e-15)

using namespace std;

mt19937 rng(chrono::steady_clock::now().time_since_epoch().count());

typedef long long ll;
typedef vector<int> vi;
typedef vector< vi > vvi;
typedef vector<double> vd;
typedef vector< vd > vvd;
typedef vector< string > vs;
typedef pair< int, int > pii;
typedef vector< pii > vpii;
typedef vector<ll> vl;
typedef vector<vector<long long>> vvl;
typedef vector<bool> vb;
typedef vector<vb> vvb;
typedef tuple<int, int, int> tiii;
const long long mod = int(1e9) + 7;
const int INF = 1e9;
const ll LINF = 1e18;


typedef pair<ll, ll> pll;

pll mysub(pll &a, pll &b)
{
	ll cz = lcm(a.second, b.second);
	ll ac = cz / a.second;
	ll bc = cz / b.second;
	ll rt = a.first * ac - b.first * bc;
	ll gcdr = gcd(abs(rt), cz);
	return pll(rt / gcdr, cz / gcdr);
}

pll myabs(pll a)
{
	if (a.first < 0)
		return pll(-a.first, a.second);
	return a;
}

int compare(pll &a, pll &b)
{
	ll cz = lcm(a.second, b.second);
	ll ac = cz / a.second;
	ll bc = cz / b.second;
	ll na = a.first * ac;
	ll nb = b.first * bc;
	if (na == nb)
		return 0;
	if (na < nb)
		return -1;
	return 1;

}

int main() {
	ios_base::sync_with_stdio(0), cin.tie(0), cout.tie(0); cout << setprecision(18) << fixed;
#ifdef LOCAL_MACHINE
	freopen("input.txt", "rt", stdin);
	freopen("output.txt", "wt", stdout);
#endif
	ll x, y, n;
	cin >> x >> y >> n;
	ll gcdxy = gcd(x, y);
	x /= gcdxy;
	y /= gcdxy;
	pll xy = { x, y };
	pair<ll, ll> rp{ 1e12, 1 };
	pair<ll, ll> rv{ 0, 0 };
	for (ll b = 1; b <= n; b++)
	{
		ll l = 0, r = 1e6;
		double maxv = (double)x / y;
		maxv += (double)rp.first / rp.second;
		maxv = (maxv + 2) * b;
		r = maxv;
		while (l <= r)
		{
			ll mid = l + (r - l) / 2;
			pll ab = { mid, b };
			pll dif = myabs(mysub(xy, ab));
			int comp = compare(dif, rp);
			if (comp == 0)
			{
				if (ab.second < rv.second)
					rv = ab;
				else if (ab.second == rv.second && ab.first < rv.first)
					rv = ab;
			}
			else if (comp < 0)
			{
				rp = dif;
				rv = ab;
			}

			if (compare(ab, xy) < 0)
				l = mid + 1;
			else
				r = mid - 1;
		}
	}
	cout << rv.first << "/" << rv.second;
	return 0;
}
